DROP TRIGGER IF EXISTS term_versions_immutable_update;
DROP TRIGGER IF EXISTS term_versions_immutable_delete;

INSERT OR REPLACE INTO term_versions
  (id, document_id, locale, version_number, body_json, created_at, effective_from)
VALUES
  ('e2e-common-zh-v1', 'common', 'zh', 1, '[{"key":"payment_methods","title":"付款方式","text":"接受銀行匯款或 PayPal。"},{"key":"deposit","title":"訂金與開工","text":"確認接受委託後，甲方支付鎖定初始報價 50% 訂金才開始製作。"},{"key":"final_payment","title":"尾款","text":"甲方確認預覽後支付尾款，再交付正式成品。"},{"key":"minor_revisions","title":"小範圍修改","text":"前 5 次小範圍修改免費；第 6 次起每次收取鎖定初始報價 10%，不累加計算基準。"},{"key":"major_revisions","title":"重大修改","text":"第 1 次重大修改免費；第 2 次起每次收取鎖定初始報價 50%。影響整體架構或處理方式時會先告知。"},{"key":"client_cancellation","title":"甲方取消","text":"甲方中途取消時訂金不退還。"},{"key":"provider_delay_completed","title":"乙方延遲但完成","text":"若 Kamel 因自身原因延遲但仍完成，總價調整為原應付總額的 60%。"},{"key":"provider_failure","title":"乙方無法完成","text":"若 Kamel 因自身原因確定無法完成，退還已收訂金。"},{"key":"client_inactivity","title":"甲方未回覆","text":"甲方連續 7 天未回覆、未提供素材或未付款時案件暫停，恢復後重新排隊。"},{"key":"queue_and_timing","title":"排程","text":"所有案件須排隊；預估工作日會依確認時與實際情況調整。"},{"key":"delivery_and_retention","title":"交付與保存","text":"正式成品交付後工程至少保存 7 日，但不保證永久保存。"},{"key":"project_file_purchase","title":"工程檔","text":"正式交付後要求工程檔，收取鎖定初始報價 50%。"},{"key":"ownership","title":"所有權","text":"甲方保有其人聲、原創歌曲、伴奏與分軌；Kamel 保有工程檔所有權。"},{"key":"confidentiality","title":"保密","text":"作品發布前或甲方同意前，Kamel 不公開委託內容。"},{"key":"credit_and_portfolio","title":"Credit 與作品集","text":"公開使用僅需提供 credit；是否允許 Kamel 放入作品集由甲方選擇。"},{"key":"progress_contact","title":"進度確認","text":"甲方可透過任何有效聯絡方式詢問進度。"},{"key":"purpose_no_price_effect","title":"用途說明","text":"用途說明用於理解需求，不影響報價。"}]', '2026-08-10T00:00:00Z', '2026-08-10T00:00:00Z'),
  ('e2e-common-en-v1', 'common', 'en', 1, '[{"key":"payment_methods","title":"Payment methods","text":"Payment is accepted by bank transfer or PayPal."},{"key":"deposit","title":"Deposit and start","text":"Work begins only after Kamel accepts the commission and the client pays a 50% deposit of the locked initial quote."},{"key":"final_payment","title":"Final payment","text":"The balance is due after the client approves the preview and before final delivery."},{"key":"minor_revisions","title":"Minor revisions","text":"The first 5 minor revisions are free. Each revision from the 6th costs 10% of the locked initial quote; the basis does not compound."},{"key":"major_revisions","title":"Major revisions","text":"The first major revision is free. Each later major revision costs 50% of the locked initial quote. Structural or processing changes are disclosed first."},{"key":"client_cancellation","title":"Client cancellation","text":"The deposit is non-refundable if the client cancels after work begins."},{"key":"provider_delay_completed","title":"Provider delay with completion","text":"If Kamel causes a delay but completes the work, the final total is adjusted to 60% of the amount otherwise due."},{"key":"provider_failure","title":"Provider cannot complete","text":"If Kamel confirms the work cannot be completed for provider-side reasons, the deposit is refunded."},{"key":"client_inactivity","title":"Client inactivity","text":"The case is paused after 7 days without a reply, required material or payment, and returns to the queue when resumed."},{"key":"queue_and_timing","title":"Queue and timing","text":"All work is queued. Estimated business days are adjusted when confirmed and may change with actual circumstances."},{"key":"delivery_and_retention","title":"Delivery and retention","text":"Project data is kept for at least 7 days after final delivery, but permanent retention is not guaranteed."},{"key":"project_file_purchase","title":"Project files","text":"Project files requested after final delivery cost 50% of the locked initial quote."},{"key":"ownership","title":"Ownership","text":"The client retains their vocals, original song, accompaniment and stems. Kamel retains ownership of project files."},{"key":"confidentiality","title":"Confidentiality","text":"Kamel keeps the work private until it is released or the client permits disclosure."},{"key":"credit_and_portfolio","title":"Credit and portfolio","text":"Public use only requires credit. The client separately chooses whether Kamel may show the work in a portfolio."},{"key":"progress_contact","title":"Progress contact","text":"The client may ask about progress through any valid contact method."},{"key":"purpose_no_price_effect","title":"Purpose","text":"The stated purpose helps clarify the request and does not affect the quote."}]', '2026-08-10T00:00:00Z', '2026-08-10T00:00:00Z'),
  ('e2e-privacy-zh-v1', 'privacy', 'zh', 1, '[{"key":"privacy_processing","title":"資料處理","text":"完整表單僅用於處理委託與聯絡，不寫入本站 D1。送出前草稿只保存在本瀏覽器。案件結束後依隱私政策清理可識別內容。"}]', '2026-08-10T00:00:00Z', '2026-08-10T00:00:00Z'),
  ('e2e-privacy-en-v1', 'privacy', 'en', 1, '[{"key":"privacy_processing","title":"Data processing","text":"The complete form is used only to process the commission and communicate. It is not stored in site D1. Unsubmitted drafts stay in this browser and identifiable data is removed under the privacy policy after the case ends."}]', '2026-08-10T00:00:00Z', '2026-08-10T00:00:00Z'),
  ('e2e-full-zh-v1', 'full-mix', 'zh', 1, '[{"key":"full_mix","title":"完整歌曲混音","text":"NT$8,000，不限軌。包含完整混音與母帶、Vocal 完整編輯與修音。交付 24-bit / 48 kHz WAV Final Master、Vocal Stem、Instrumental Mix Stem；預估 7–14 工作日。"},{"key":"mixing_source","title":"混音素材","text":"提交乾／原始未處理檔案，盡可能使用 24-bit / 48 kHz WAV 並正確命名。其他格式造成的音質下降由甲方承擔；未整理素材可退回或經同意加收服務基價 5%。"}]', '2026-08-10T00:00:00Z', '2026-08-10T00:00:00Z'),
  ('e2e-full-en-v1', 'full-mix', 'en', 1, '[{"key":"full_mix","title":"Full Song Mixing","text":"NT$8,000 base with unlimited tracks. Includes full mixing and mastering plus complete vocal editing and tuning. Delivery: 24-bit / 48 kHz WAV Final Master, Vocal Stem and Instrumental Mix Stem. Estimate: 7–14 business days."},{"key":"mixing_source","title":"Mixing source material","text":"Submit dry, unprocessed files, preferably correctly named 24-bit / 48 kHz WAV. The client accepts quality loss caused by other formats. Unprepared material may be returned or handled for an agreed 5% service-base fee."}]', '2026-08-10T00:00:00Z', '2026-08-10T00:00:00Z'),
  ('e2e-vocal-zh-v1', 'vocal-mix', 'zh', 1, '[{"key":"vocal_mix","title":"Vocal 混音","text":"NT$4,000，不限軌。包含和音編輯、修音、對拍、效果設計、與既有伴奏融合、混音及母帶。交付三種 24-bit / 48 kHz WAV；預估 5–7 工作日。"},{"key":"mixing_source","title":"混音素材","text":"提交乾／原始未處理檔案，盡可能使用 24-bit / 48 kHz WAV 並正確命名。其他格式造成的音質下降由甲方承擔；未整理素材可退回或經同意加收服務基價 5%。"}]', '2026-08-10T00:00:00Z', '2026-08-10T00:00:00Z'),
  ('e2e-vocal-en-v1', 'vocal-mix', 'en', 1, '[{"key":"vocal_mix","title":"Vocal Mixing","text":"NT$4,000 base with unlimited tracks. Includes harmony editing, tuning, timing, effects, integration with an existing instrumental, mixing and mastering. Three 24-bit / 48 kHz WAV outputs; estimate 5–7 business days."},{"key":"mixing_source","title":"Mixing source material","text":"Submit dry, unprocessed files, preferably correctly named 24-bit / 48 kHz WAV. The client accepts quality loss caused by other formats. Unprepared material may be returned or handled for an agreed 5% service-base fee."}]', '2026-08-10T00:00:00Z', '2026-08-10T00:00:00Z'),
  ('e2e-simple-zh-v1', 'simple-transition', 'zh', 1, '[{"key":"simple_transition","title":"單純歌曲銜接","text":"1–5 首 NT$1,000，第 6 首起每首 NT$200。僅做銜接與必要效果，不做結構編輯。順序與銜接點必填；需 Kamel 協助決策時加收服務基價 50% 諮詢費。目標總長度、是否無縫與風格必填；預估 3–5 工作日。"},{"key":"transition_delivery","title":"來源與交付","text":"來源需盡可能高音質；來源品質造成的損失由甲方承擔。交付 24-bit / 48 kHz WAV、MP3 與 AAC。"},{"key":"schedule_adjustment","title":"排程與急件","text":"完工日依排程與素材狀態調整。急件須先協議並加收服務基價 50%。"}]', '2026-08-10T00:00:00Z', '2026-08-10T00:00:00Z'),
  ('e2e-simple-en-v1', 'simple-transition', 'en', 1, '[{"key":"simple_transition","title":"Simple Song Transition","text":"NT$1,000 for 1–5 songs, then NT$200 per additional song. Includes transitions and necessary effects only, without structural editing. Order and transition points are required; Kamel decision support adds a 50% service-base consultation fee. Target length, seamless playback and style are required. Estimate: 3–5 business days."},{"key":"transition_delivery","title":"Sources and delivery","text":"Provide the highest practical source quality. The client accepts loss caused by source quality. Delivery includes 24-bit / 48 kHz WAV, MP3 and AAC."},{"key":"schedule_adjustment","title":"Schedule and rush","text":"Completion depends on the actual queue and source readiness. Rush work must be agreed first and adds 50% of the service base."}]', '2026-08-10T00:00:00Z', '2026-08-10T00:00:00Z'),
  ('e2e-edit-zh-v1', 'edit-transition', 'zh', 1, '[{"key":"edit_transition","title":"編輯／剪輯歌曲銜接","text":"1–5 首 NT$4,000，第 6 首起每首 NT$800。包含刪減、重排、速度／音高、音效、延長開頭／結尾、混音平衡與重新母帶。時長、銜接點、總長度與風格必填，參考連結選填；預估 7–14 工作日。"},{"key":"transition_delivery","title":"來源與交付","text":"來源需盡可能高音質；來源品質造成的損失由甲方承擔。交付 24-bit / 48 kHz WAV、MP3 與 AAC。"},{"key":"schedule_adjustment","title":"排程與急件","text":"完工日依排程與素材狀態調整。急件須先協議並加收服務基價 50%。"}]', '2026-08-10T00:00:00Z', '2026-08-10T00:00:00Z'),
  ('e2e-edit-en-v1', 'edit-transition', 'en', 1, '[{"key":"edit_transition","title":"Edited Song Transition","text":"NT$4,000 for 1–5 songs, then NT$800 per additional song. Includes cuts, restructuring, tempo or pitch changes, effects, extended intros or endings, mix balance and remastering. Segment length, transition point, target length and style are required; references are optional. Estimate: 7–14 business days."},{"key":"transition_delivery","title":"Sources and delivery","text":"Provide the highest practical source quality. The client accepts loss caused by source quality. Delivery includes 24-bit / 48 kHz WAV, MP3 and AAC."},{"key":"schedule_adjustment","title":"Schedule and rush","text":"Completion depends on the actual queue and source readiness. Rush work must be agreed first and adds 50% of the service base."}]', '2026-08-10T00:00:00Z', '2026-08-10T00:00:00Z');

