CREATE TRIGGER term_versions_immutable_update
BEFORE UPDATE ON term_versions
BEGIN
  SELECT RAISE(ABORT, 'term_version_immutable');
END;

CREATE TRIGGER term_versions_immutable_delete
BEFORE DELETE ON term_versions
BEGIN
  SELECT RAISE(ABORT, 'term_version_immutable');
END;
